/***************************************************************************//**
* \file gfxss_ip_compat.h
* \version 1.0
*
* \brief
* Compatibility macros for GFXSS IP header naming differences between platforms.
* PSE84 (cyip_gfxss.h) uses doubled register names: REGNAME_REGNAME_FIELD
* PSE8X7 (cyip_gfxss_v1_2.h) uses shorter: REGNAME_FIELD
* This header maps the long form to short form when not already defined.
*
********************************************************************************
* \copyright
* (c) 2024-2026, Infineon Technologies AG or an affiliate of
* Infineon Technologies AG.
* SPDX-License-Identifier: Apache-2.0
*******************************************************************************/

